	@Override
	public void renderAll(PoseStack pose, VertexConsumer vc, int light, int overlay, BlockEntity te, List<?> li, float phi, float theta) {

		boolean broken = (Boolean)li.get(0);
		Shape1.render(pose, vc, light, overlay);

		pose.translate(0, 1, 0);
		pose.mulPose(TechneModel.rotation(phi, 0, 1, 0));
		pose.translate(0, -1, 0);
		Shape3.render(pose, vc, light, overlay);
		Shape4.render(pose, vc, light, overlay);

		if (!broken) {
			pose.translate(0, 1, 0);
			pose.mulPose(TechneModel.rotation(theta, 1, 0, 0));
			pose.translate(0, -1, 0);
			Shape5.render(pose, vc, light, overlay);
			Shape5b.render(pose, vc, light, overlay);
			Shape5c.render(pose, vc, light, overlay);
			Shape5d.render(pose, vc, light, overlay);
			pose.translate(0, 1, 0);
			pose.mulPose(TechneModel.rotation(-theta, 1, 0, 0));
			pose.translate(0, -1, 0);
		}

		Shape3a.render(pose, vc, light, overlay);
		Shape3b.render(pose, vc, light, overlay);
		Shape3c.render(pose, vc, light, overlay);
		Shape3d.render(pose, vc, light, overlay);
		Shape3as.render(pose, vc, light, overlay);

		double sc = 1-0.725*Math.cos(Math.toRadians(theta))*Math.sin(Math.toRadians(-theta));
		double d = 1.5;
		pose.translate(0, d, 0);
		pose.scale(1, (float)sc, 1);
		pose.translate(0, -d, 0);
		Shape5a.render(pose, vc, light, overlay);
		Shape5af.render(pose, vc, light, overlay);
		Shape5as.render(pose, vc, light, overlay);
		pose.translate(0, d, 0);
		pose.scale(1, (float)(1D/sc), 1);
		pose.translate(0, -d, 0);


		pose.translate(0, 1, 0);
		pose.mulPose(TechneModel.rotation(-phi, 0, 1, 0));
		pose.translate(0, -1, 0);
	}

